/**
 * WebMCP tools for autowebmcp.com
 * Generated by Auto WebMCP by Satsuma.ai
 *
 * Spec: https://developer.chrome.com/docs/ai/webmcp/imperative-api
 * Load with: <script type="module" src="/webmcp-tools.js"></script>
 *
 * document.modelContext is the current surface; navigator.modelContext is kept
 * only as a deprecated fallback for older builds and the WebMCP polyfill.
 * Every fetch below is same-origin and sends no credentials.
 */

const modelContext =
  ("modelContext" in document && document.modelContext) ||
  ("modelContext" in navigator && navigator.modelContext);

if (!modelContext) {
  console.info("[webmcp] Browser has no WebMCP support - nothing registered.");
} else {
  const controller = new AbortController();
  window.addEventListener("pagehide", () => controller.abort(), { once: true });

  const encodeQuery = (values) => {
    const params = new URLSearchParams(
      Object.entries(values).flatMap(([key, value]) =>
        value == null ? [] : [[key, Array.isArray(value) ? value.join(",") : String(value)]],
      ),
    );
    const query = params.toString();
    return query ? `?${query}` : "";
  };

  const parseJson = async (res) => {
    if (!res.ok) return `Request failed with status ${res.status}.`;
    const data = await res.json().catch(() => null);
    return data == null ? "Request succeeded but returned no JSON body." : JSON.stringify(data);
  };

  const readTool = ({ name, description, properties, required, endpoint }) => ({
    name,
    description,
    inputSchema: { type: "object", properties, required },
    annotations: { readOnlyHint: true, destructiveHint: false, untrustedContentHint: true },
    execute: async (args, { signal } = {}) => {
      const res = await fetch(`${endpoint}${encodeQuery(args ?? {})}`, {
        signal: signal || controller.signal,
        headers: { accept: "application/json" },
      });
      return parseJson(res);
    },
  });

  const GENERATION_ID = {
    type: "string",
    description: "The unique ID returned by generate_webmcp_tools.",
  };

  const tools = [
    {
      name: "generate_webmcp_tools",
      description:
        "Initiates scanning a target website and generating WebMCP tools based on its structure and content. Requires website_url. Returns a unique generation ID.",
      inputSchema: {
        type: "object",
        properties: {
          website_url: {
            type: "string",
            description:
              "The URL of the target website for which to generate WebMCP tools, for example https://www.example.com.",
          },
        },
        required: ["website_url"],
      },
      annotations: { readOnlyHint: false, destructiveHint: false, untrustedContentHint: true },
      execute: async ({ website_url }, { signal } = {}) => {
        if (!window.confirm(`Generate WebMCP tools for ${website_url}?`)) {
          return "Generation cancelled by the user.";
        }
        const res = await fetch("/api/generate", {
          method: "POST",
          signal: signal || controller.signal,
          headers: { "content-type": "application/json", accept: "application/json" },
          body: JSON.stringify({ website_url }),
        });
        return parseJson(res);
      },
    },
    readTool({
      name: "get_generation_status",
      description:
        "Retrieves the current status and progress of a WebMCP tool generation request. Requires generation_id.",
      properties: { generation_id: GENERATION_ID },
      required: ["generation_id"],
      endpoint: "/api/status",
    }),
    readTool({
      name: "list_generated_tools",
      description:
        "Lists generated WebMCP tools for a specific generation request. Requires generation_id.",
      properties: { generation_id: GENERATION_ID },
      required: ["generation_id"],
      endpoint: "/api/tools",
    }),
    readTool({
      name: "get_tool_details",
      description:
        "Retrieves full schema and details for a generated WebMCP tool. Requires generation_id and tool_name.",
      properties: {
        generation_id: GENERATION_ID,
        tool_name: { type: "string", description: "The generated tool name to retrieve." },
      },
      required: ["generation_id", "tool_name"],
      endpoint: "/api/tool_details",
    }),
    readTool({
      name: "get_agent_code_snippet",
      description:
        "Returns a code snippet for registering generated WebMCP tools in coding agents. Requires generation_id.",
      properties: { generation_id: GENERATION_ID },
      required: ["generation_id"],
      endpoint: "/api/agent_code",
    }),
    readTool({
      name: "get_cdn_deployment_instructions",
      description:
        "Returns step-by-step deployment instructions for generated WebMCP tools on a CDN or edge platform. Requires generation_id and cdn_platform.",
      properties: {
        generation_id: GENERATION_ID,
        cdn_platform: {
          type: "string",
          description:
            "Target CDN or edge platform, for example Cloudflare Workers, Akamai EdgeWorkers, Netlify Edge Functions, or Vercel.",
        },
      },
      required: ["generation_id", "cdn_platform"],
      endpoint: "/api/cdn_deploy",
    }),
  ];

  for (const tool of tools) {
    await modelContext.registerTool(tool, { signal: controller.signal });
  }

  document.modelContext?.addEventListener?.("toolchange", () => {
    console.debug("[webmcp] tool set changed");
  });
}
